def transform(g):
    H,W=len(g),len(g[0])
    fg=6 if any(6 in r for r in g) else 9
    bg=9 if fg==6 else 1
    from collections import deque
    seen=[[False]*W for _ in g]
    for i in range(H):
        for j in (0,W-1):
            if g[i][j]==bg and not seen[i][j]:
                q=deque([(i,j)]); seen[i][j]=True
                while q:
                    x,y=q.popleft()
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<H and 0<=b<W and g[a][b]==bg and not seen[a][b]:
                            seen[a][b]=True; q.append((a,b))
    for j in range(W):
        for i in (0,H-1):
            if g[i][j]==bg and not seen[i][j]:
                q=deque([(i,j)]); seen[i][j]=True
                while q:
                    x,y=q.popleft()
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<H and 0<=b<W and g[a][b]==bg and not seen[a][b]:
                            seen[a][b]=True; q.append((a,b))
    return [[4 if g[i][j]==bg and not seen[i][j] else g[i][j] for j in range(W)] for i in range(H)]

